INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13901, 'Psalms 66:16', 'Psalms', 66, 16, '&nbsp;ما ته راشئ او غوږ ونيسئ تاسو ټول څوک چې د خُدائ پاک نه يرېږئ، نو تاسو ته به زۀ اوس ووايم چې هغۀ ما له څۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13902, 'Psalms 66:17', 'Psalms', 66, 17, '&nbsp;په خپله خولۀ ما هغۀ ته سوال زارى وکړه او زما ژبې د هغۀ ثناء صِفت بيان کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13903, 'Psalms 66:18', 'Psalms', 66, 18, '&nbsp;کۀ زما په زړۀ کښې د ګناه دپاره ځائ وو، نو مالِک خُدائ به زما سوال اورېدلے نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13904, 'Psalms 66:19', 'Psalms', 66, 19, '&nbsp;خو بې‌شکه خُدائ پاک ما ته غوږ نيولے دے، او هغۀ زما د دُعا آواز اورېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13905, 'Psalms 66:20', 'Psalms', 66, 20, '&nbsp;ثناء صِفت دې هغه خُدائ پاک ته وى چا چې زما دُعا رد نۀ کړه، هغۀ خپله ابدى مينه ما سره ختمه نۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13906, 'Psalms 67:1', 'Psalms', 67, 1, '&nbsp;خُدائ پاک دې په مونږ مهربانه شى او مونږ ته دې برکت راکړى، او په مونږ دې د خپل مخ نُور وځلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13907, 'Psalms 67:2', 'Psalms', 67, 2, '&nbsp;او په ټوله دُنيا کښې دې ستا لارې وپېژندلے شى، ستا د خلاصون نه دې ټول قومونه خبر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13908, 'Psalms 67:3', 'Psalms', 67, 3, '&nbsp;اے پاکه خُدايه، په ټولو قومونو دې ستا ثناء صِفت بيان شى، او ټول قومونه دې ستا ثناء خوان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13909, 'Psalms 67:4', 'Psalms', 67, 4, '&nbsp;ټول قومونه دې ستا خوشحالى وکړى او د خوښې سندرې دې ووائى، ځکه چې تۀ د قومونو اِنصاف کوې او د دُنيا خلقو ته لارښودنه کوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13910, 'Psalms 67:5', 'Psalms', 67, 5, '&nbsp;ټول قومونه دې ستا ثناء صِفت بيان کړى، اے پاکه خُدايه، ستا په صِفت دې ټول قومونه ثناء خوان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13911, 'Psalms 67:6', 'Psalms', 67, 6, '&nbsp;نو بيا به زمکه خپل پېداوار ورکړى، خُدائ پاک زمونږ خُدائ به مونږ له برکت راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13912, 'Psalms 67:7', 'Psalms', 67, 7, '&nbsp;خُدائ پاک به مونږ له برکت راکړى، او د دُنيا تر آخره ټول خلق به د هغۀ نه ويره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13913, 'Psalms 68:1', 'Psalms', 68, 1, '&nbsp;پاکه خُدايه راپاڅه، او خپل دشمنان دې خوارۀ وارۀ کړه، څوک چې تا نه نفرت کوى هغوئ تالا والا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13914, 'Psalms 68:2', 'Psalms', 68, 2, '&nbsp;لکه څنګه چې لوګے د هوا په وړاندې زغلى، دغه شان تاسو دوئ د خپل ځان نه وزغلوئ. لکه څنګه چې موم د اور په مخکښې ويلې کيږى، دغه شان دې بدکاره خلق د خُدائ پاک په وړاندې تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13915, 'Psalms 68:3', 'Psalms', 68, 3, '&nbsp;خو صادقان دې د هغۀ په وړاندې خوشحالى وکړى، د خُدائ پاک په حضور کښې دې خوشحاله شى، او د خوښۍ نعرې دې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13916, 'Psalms 68:4', 'Psalms', 68, 4, '&nbsp;خُدائ پاک ته سرود ووايئ، او د هغۀ د نوم ثناء صِفت بيان کړئ، څوک چې سور په وريځو راځى هغه دروند کړئ، د هغۀ نوم مالِک خُدائ دے او د هغۀ په وړاندې خوشحالى وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13917, 'Psalms 68:5', 'Psalms', 68, 5, '&nbsp;د يتيمانو دپاره پلار دے او د کونډو حفاظت کوى، هم دا خُدائ پاک دے څوک چې په خپل مقدس ځائ کښې سکونت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13918, 'Psalms 68:6', 'Psalms', 68, 6, '&nbsp;تۀ بې‌کسه ته خاندان او قېدى ته خوشحالى او آزادى ورکوى. خو سرکشه خلق په اوچو او سوکړو کښې ژوند کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13919, 'Psalms 68:7', 'Psalms', 68, 7, '&nbsp;اے پاکه خُدايه، کله چې تۀ د خپلو خلقو لارښود وې، او په بيابان کښې د هغوئ په وړاندې روان وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13920, 'Psalms 68:8', 'Psalms', 68, 8, '&nbsp;زمکه وخوځېدله او باران د بره آسمانه وورېدو د خُدائ پاک په وړاندې، د سينا په صحرا کښې او د بنى اِسرائيل د خُدائ پاک په وړاندې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13921, 'Psalms 68:9', 'Psalms', 68, 9, '&nbsp;په شيبو شيبو باران دې راشروع کړو پاکه خُدايه. ترڅو تۀ خُشکه زمکه کړې تازه او آباده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13922, 'Psalms 68:10', 'Psalms', 68, 10, '&nbsp;ستا غوره شوى خلق په هغه ځائ کښې اوسېدل. پاکه خُدايه، تا مسکينان د خپل سخاوت په وجه ماړۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13923, 'Psalms 68:11', 'Psalms', 68, 11, '&nbsp;مالِک خُدائ حُکم وکړو، او ډېرو ګڼو ښځو دا زېرے ورسولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13924, 'Psalms 68:12', 'Psalms', 68, 12, '&nbsp;”بادشاهان سره د فوجه وتښتېدل.“ په کور کښې ښځو د غنيمت مالونه تقسيم کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13925, 'Psalms 68:13', 'Psalms', 68, 13, '&nbsp;هغوئ خزانې وموندلې کۀ څۀ هم څوک چې شپول کښې اوسېدل، کونترې چې د سپينو زرو وزرونه يې وُو او بڼې يې د سرو زرو وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13926, 'Psalms 68:14', 'Psalms', 68, 14, '&nbsp;کله چې قادر خُدائ ټول بادشاهان خوارۀ وارۀ کړل، د واورې په شان په ضلمون غر ورېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13927, 'Psalms 68:15', 'Psalms', 68, 15, '&nbsp;بسن غرونه څومره اوچت دى، د بسن د غرۀ ډيرې دنګې څوکې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13928, 'Psalms 68:16', 'Psalms', 68, 16, '&nbsp;اے لوړو غرونو تاسو ولې د حسد په نظر ګورئ، هغه غرونو ته کوم چې خُدائ د خپل ځان د اوسېدو دپاره منتخب کړى دى؟ چرته چې به مالِک خُدائ د تل دپاره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13929, 'Psalms 68:17', 'Psalms', 68, 17, '&nbsp;د مالِک خُدائ جنګى ګاډۍ دى په سلګونو او زرګونو. مالِک خُدائ د سينا د غرۀ نه خپل مقدس ځائ ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13930, 'Psalms 68:18', 'Psalms', 68, 18, '&nbsp;کله چې تۀ بره لاړې قېديان دې ځان سره بوتلل. د بنيادمو نه درته تحفې مِلاو شوې د هغوئ نه هم کومو چې بغاوت کړے وو. نو هم داسې مالِک خُدائ هلته استوګنه وکړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13931, 'Psalms 68:19', 'Psalms', 68, 19, '&nbsp;زمونږ خلاصونکى مالِک خُدائ ته دې ثناء وى، څوک چې هره ورځ زمونږ بوج وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13932, 'Psalms 68:20', 'Psalms', 68, 20, '&nbsp;زمونږ قادر مطلق خُدائ هغه مالِک خُدائ دے څوک چې خلاصون ورکوى، قادر مطلق خُدائ څوک چې مونږ د مرګ نه خلاصوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13933, 'Psalms 68:21', 'Psalms', 68, 21, '&nbsp;خو مالِک خُدائ به د خپلو دشمنانو سر هوار کړى، او د هغوئ کوپړۍ به هواره ‎کړى څوک چې د ګناه په لار روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13934, 'Psalms 68:22', 'Psalms', 68, 22, '&nbsp;مالِک خُدائ وفرمائيل، ”زۀ به خپل دشمنان د بسن نه واپس راښکته کړم، زۀ به هغوئ د سمندر د تل نه راوباسم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13935, 'Psalms 68:23', 'Psalms', 68, 23, '&nbsp;تاسو به د هغوئ په وينو کښې خپلې پښې ووينځئ، او ستاسو سپى به خپله حِصه په خپلو ژبو وڅټى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13936, 'Psalms 68:24', 'Psalms', 68, 24, '&nbsp;اے پاکه خُدايه، ستا جلوس هر چا وليدلو، زما د خُدائ پاک او زما د بادشاه جلوس چې مقدس ځائ ته داخلېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13937, 'Psalms 68:25', 'Psalms', 68, 25, '&nbsp;سندرغاړى ترې نه وړاندې او ورپسې موسيقاران دى، او په مينځ کښې يې پېغلې جينکۍ دى چې تمبلونه غږوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13938, 'Psalms 68:26', 'Psalms', 68, 26, '&nbsp;”په لويو ډلو کښې د خُدائ پاک ثناء صِفت ادا کړئ، د بنى اِسرائيلو په جماعت کښې د مالِک خُدائ صِفت وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13939, 'Psalms 68:27', 'Psalms', 68, 27, '&nbsp;د بنيامين وړه قبيله د دوئ لارښودنه کوى، بيا ورپسې د يهوداه شهزادګان راروان دى، په هغوئ پسې د زبولون او نفتالى شهزادګان راروان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13940, 'Psalms 68:28', 'Psalms', 68, 28, '&nbsp;پاکه خُدايه، خپل زور دې وښايه. لکه څنګه چې تا مخکښې ښودلے وو مونږ ته خپل زور بيا وښايه، پاکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13941, 'Psalms 68:29', 'Psalms', 68, 29, '&nbsp;ستا د مقدس کور په خاطر چې په يروشلم کښې دے، بادشاهان تا له تحفې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13942, 'Psalms 68:30', 'Psalms', 68, 30, '&nbsp;مِصر ورټه څوک چې د وحشى ځناورو په شان د لوخو په ځنګل کښې اوسيږى، او هغه قومونه چې د ځنګلى غوَيانو د رمو په شان د سخو په مينځ کښې دى ورټه، او دوئ عاجزه کړه چې تا ته د سپينو زرو نذرانې وړاندې کړى. هغه خلق خوارۀ وارۀ کړه څوک چې د جنګ شوق کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13943, 'Psalms 68:31', 'Psalms', 68, 31, '&nbsp;مِصريان دې د زېړو د قيمتى تُحفو سره راشى، او د ايتهوپيا خلق دې خُدائ ته لاس په دُعا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13944, 'Psalms 68:32', 'Psalms', 68, 32, '&nbsp;د دُنيا بادشاهتونو د خُدائ د لويئ سندرې ووايئ، مالِک خُدائ ته سندرې ووايئ او ثناء صِفت بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13945, 'Psalms 68:33', 'Psalms', 68, 33, '&nbsp;د هغۀ ثناء صِفت وکړئ څوک چې په عرش باندې د ازل نه ناست دى، هغه چا ته څوک چې په دروند آواز غږيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13946, 'Psalms 68:34', 'Psalms', 68, 34, '&nbsp;خُدائ پاک په خپل قدرت کښې وستايئ، د چا چې دبدبه په بنى اِسرائيلو او زور په آسمانونو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13947, 'Psalms 68:35', 'Psalms', 68, 35, '&nbsp;په خپل مقدس ځائ کښې ستا شان څومره لوئ دے، پاکه خُدايه، د بنى اِسرائيلو خُدائ پاک طاقت او قدرت ورکوى خپلو خلقو ته، ثناء صِفت دې وى خُدائ پاک ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13948, 'Psalms 69:1', 'Psalms', 69, 1, '&nbsp;اے پاکه خُدايه، ما بچ کړه، ځکه چې سېلاب مې تر مرۍ رارسېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13949, 'Psalms 69:2', 'Psalms', 69, 2, '&nbsp;زما د پښو دپاره کلکه زمکه نشته خټو کښې ډوبېږم په ژورو اوبو کښې سېلاب راګېر کړے يم ډوبېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13950, 'Psalms 69:3', 'Psalms', 69, 3, '&nbsp;مرۍ مې وُچه شوه په چغو ستړے شوم، خُدائ ته په انتظار کولو مې نظر کم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13951, 'Psalms 69:4', 'Psalms', 69, 4, '&nbsp;څوک چې ما نه نفرت کوى زما د سر وېښتو نه زيات دى. هغوئ بې‌سببه ما سره دشمنى کوى او چې ما ختمول غواړى ډېر دى. هغوئ رانه هغه څۀ واپس غواړى چې مې پټ کړى نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13952, 'Psalms 69:5', 'Psalms', 69, 5, '&nbsp;اے پاکه خُدايه، تا ته پته ده چې زۀ څومره بې‌وقوفه يم، او ستا نه پټ نۀ دى زما ګناهونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13953, 'Psalms 69:6', 'Psalms', 69, 6, '&nbsp;اے مالِکه خُدايه، ربُ الافواج خُدايه څوک چې په تا باندې توکل کوى، هغوئ دې زما په وجه شرمنده نۀ شى څوک چې ستا لټون کوى. اے د بنى اِسرائيل خُدايه، هغوئ دې زما په وجه شرمنده نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13954, 'Psalms 69:7', 'Psalms', 69, 7, '&nbsp;ستا دپاره ما د خلقو سپکاوے برداشت کړو او د شرم په وجه ما خپل سر ښکته کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13955, 'Psalms 69:8', 'Psalms', 69, 8, '&nbsp;تر دې چې خپلو وروڼو راته د پردو نظر وکړو، او زۀ په خپلو وروڼو کښې پردے شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13956, 'Psalms 69:9', 'Psalms', 69, 9, '&nbsp;ستا د کور غېرت دپاره زۀ وسوزېدم، څوک چې تا سپکوى د هغوئ سپکوالے زۀ برداشت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13957, 'Psalms 69:10', 'Psalms', 69, 10, '&nbsp;کله چې زۀ ژاړم او روژه ونيسم، نو دوئ په ما پورې خندا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13958, 'Psalms 69:11', 'Psalms', 69, 11, '&nbsp;کله چې زۀ د ټاټ جامې واچوم نو دوئ په ما پورې خندا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13959, 'Psalms 69:12', 'Psalms', 69, 12, '&nbsp;په لارو کوڅو کښې ما پورې ټوقې کوى، شرابيان مې په بې‌عزتۍ سره په سندرو کښې يادوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13960, 'Psalms 69:13', 'Psalms', 69, 13, '&nbsp;خو مالِکه خُدايه، په مناسب وخت کښې دې زما دُعا واوره، په خپله لويه مينه کښې دې زما د خلاصون سوال قبول کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13961, 'Psalms 69:14', 'Psalms', 69, 14, '&nbsp;ما په خټو کښې د ډوبېدو نه بچ کړه، څوک چې رانه نفرت کوى د هغوئ نه ما بچ کړه، او د ژورو اوبو نه مې رابهر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13962, 'Psalms 69:15', 'Psalms', 69, 15, '&nbsp;زما د سر دپاسه سېلاب تېرېدو ته مۀ پرېږده، په اوبو کښې ډوبېدو ته مې مۀ پرېږده، او لحد ته غورزېدو ته مې مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13963, 'Psalms 69:16', 'Psalms', 69, 16, '&nbsp;اے مالِکه خُدايه، د خپلې ابدى مينې په نېکۍ کښې دې زما سوال قبول کړه، او په خپله لويه مهربانۍ کښې دې ما ته خپل مخ راواړوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13964, 'Psalms 69:17', 'Psalms', 69, 17, '&nbsp;د خپل بنده نه دې مخ مۀ پټوه، په سختۍ کښې راګېر يمه دُعا مې زر قبوله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13965, 'Psalms 69:18', 'Psalms', 69, 18, '&nbsp;ما له نزدې راشه او په قيمت مې واخله، ما د خپلو دشمنانو د لاس نه خلاص کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13966, 'Psalms 69:19', 'Psalms', 69, 19, '&nbsp;تا ته پته ده چې زۀ څومره بې‌عزته شوم او څومره وشرمولے شوم، زما ټول دشمنان ستا په وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13967, 'Psalms 69:20', 'Psalms', 69, 20, '&nbsp;ډېرې بې‌عزتۍ مې زړۀ مات کړے دے نااُميده يم، څوک نۀ وُو چې په ما يې رحم کړے وے، يو هم نۀ وو، څوک نۀ وُو چې ما له يې تسلى راکړے وے، يو هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13968, 'Psalms 69:21', 'Psalms', 69, 21, '&nbsp;د روټۍ په ځائ يې زهر راله راکړل، د اوبو په ځائ سرکه يې راله راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13969, 'Psalms 69:22', 'Psalms', 69, 22, '&nbsp;د هغوئ دسترخوان دې د هغوئ دپاره جال او دام شى، او د هغوئ مال دولت دې ورته دام وګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13970, 'Psalms 69:23', 'Psalms', 69, 23, '&nbsp;سترګې يې ړندې کړه چې هغوئ ونۀ وينى، او د هغوئ ملاګانې دې د تل دپاره ټيټې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13971, 'Psalms 69:24', 'Psalms', 69, 24, '&nbsp;تۀ دې خپل قهر په هغوئ نازل کړه، او ستا هيبتناکه غصه دې هغوئ راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13972, 'Psalms 69:25', 'Psalms', 69, 25, '&nbsp;د هغوئ کورونه دې وران شى، د هغوئ په خېمو کښې دې د اوسېدو هيڅ څوک پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13973, 'Psalms 69:26', 'Psalms', 69, 26, '&nbsp;چا له چې تا سزا ورکړه په هغوئ ظلم کوى، او ورله په زخمونو باندې مالګې دوړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13974, 'Psalms 69:27', 'Psalms', 69, 27, '&nbsp;هغوئ سره د ټولو ګناهونو ذره ذره حساب وکړه، او په خپل خلاصون کښې ورته برخه مۀ ورکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13975, 'Psalms 69:28', 'Psalms', 69, 28, '&nbsp;د هغوئ نومونه دې د ژوندون د کِتاب نه لرې شى، د صادقانو په شمېر کښې دې حساب نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13976, 'Psalms 69:29', 'Psalms', 69, 29, '&nbsp;په درد کښې يم او په ما باندې سختى ده، اے پاکه خُدايه، په خپل خلاصون دې ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13977, 'Psalms 69:30', 'Psalms', 69, 30, '&nbsp;زۀ به د خُدائ د نوم ثناء صِفت وکړم، په شُکر ګزارۍ سره به د هغۀ عزت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13978, 'Psalms 69:31', 'Psalms', 69, 31, '&nbsp;دا به مالِک خُدائ د غوَيى د قربانۍ نه زيات خوشحاله کړى، د دې نه زيات چې پوره غوَيے ورته د ښکرونو او سومونو سره وړاندې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13979, 'Psalms 69:32', 'Psalms', 69, 32, '&nbsp;مظلومان چې دا ووينى نو ډېر به خوشحاله شى، څوک چې د خُدائ پاک لټون کوى نو هغوئ به هم ډاډه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13980, 'Psalms 69:33', 'Psalms', 69, 33, '&nbsp;ځکه چې د مظلومانو ژړا مالِک خُدائ په خپله اورى، او هغه کله هم خپل قېديان نۀ هېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13981, 'Psalms 69:34', 'Psalms', 69, 34, '&nbsp;اے زمکې او آسمانه د خُدائ ثناء ووايئ، سمندرونو او هر څۀ چې په کښې ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13982, 'Psalms 69:35', 'Psalms', 69, 35, '&nbsp;خُدائ به صيون بچ کړى او دوباره به د يهوداه ښارونه آباد کړى، نو خلق به هغه ځائ کښې اوسيږى او دوئ ته به يې په ميراث کښې ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13983, 'Psalms 69:36', 'Psalms', 69, 36, '&nbsp;د هغۀ د خِدمتګارانو اولاد ته به يې ميراث کښې ورکړى، هغوئ به په کښې اوسيږى څوک چې د هغۀ د نوم سره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13984, 'Psalms 70:1', 'Psalms', 70, 1, '&nbsp;پاکه خُدايه، ما ته خلاصون راکړه، مالِکه خُدايه، زر راشه، او زما مدد وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13985, 'Psalms 70:2', 'Psalms', 70, 2, '&nbsp;هغوئ څوک چې زما د مړ کولو کوشش کوى، هغوئ دې شرمنده او سرګردانه شى، هغوئ ټول څوک چې زما تباه کېدل غواړى، دوئ ټول دې شکست وخورى او شرمنده دې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13986, 'Psalms 70:3', 'Psalms', 70, 3, '&nbsp;هغه څوک چې ما پورې خندا کوى، هغوئ دې ماتے وخورى وارخطا دې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13987, 'Psalms 70:4', 'Psalms', 70, 4, '&nbsp;هغوئ څوک چې ستا لټون کښې ګرځى، هغوئ دې خوښى وکړى او خوشحاله دې شى، څوک چې ستا خلاصون سره مينه کوى، همېشه دې د مالِک خُدائ لوئى بيانوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13988, 'Psalms 70:5', 'Psalms', 70, 5, '&nbsp;زۀ ډېر غريب او حاجتمند يم، اے خُدايه، ما له زر راشه، اے زما مددګاره او خلاصوونکيه، اے مالِکه خُدايه، نور انتظار مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13989, 'Psalms 71:1', 'Psalms', 71, 1, '&nbsp;زما مالِکه خُدايه ستا پناه له راغلے يم، ما مۀ پرېږده چې په شرم وشرمېږم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13990, 'Psalms 71:2', 'Psalms', 71, 2, '&nbsp;په خپل صداقت سره دې ما بچ کړه او خلاصون راکړه، ما ته غوږ ونيسه او ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13991, 'Psalms 71:3', 'Psalms', 71, 3, '&nbsp;تۀ زما د پناه ګټ شه چرته چې زۀ هر وخت ورتلے شم، تۀ حُکم ورته وکړه چې زۀ په کښې بچ شم. ځکه چې تۀ يې زما ګټ او قلعه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13992, 'Psalms 71:4', 'Psalms', 71, 4, '&nbsp;زما پاکه خُدايه، ما د بدعملو د لاسونو نه خلاص کړه، او د بدکارانو او ظالمانو د قبضې نه مې خلاص کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13993, 'Psalms 71:5', 'Psalms', 71, 5, '&nbsp;اے قادر مطلق مالِکه خُدايه صرف تۀ زما اُميد يې، او د ورکوټوالى نه په تا باندې توکل کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13994, 'Psalms 71:6', 'Psalms', 71, 6, '&nbsp;زما د پېدا کېدو سره سم ما هم په تا بهروسه کړې ده، او هم تا زما خيال وساتلو د مور په ګېډه. زۀ به همېشه ستا ثناء صِفت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13995, 'Psalms 71:7', 'Psalms', 71, 7, '&nbsp;د ډېرو خلقو په وړاندې عجيبه غوندې مثال ګرځېدلے يم، خو تۀ مضبوطه پناه ګاه يې زما دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13996, 'Psalms 71:8', 'Psalms', 71, 8, '&nbsp;ټوله ورځ زۀ په ژبه ستا ثناء صِفت کوم، ستا شان او شوکت ټوله ورځ بيانوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13997, 'Psalms 71:9', 'Psalms', 71, 9, '&nbsp;په بوډاوالى کښې چې ما ونۀ غورزوې، هرکله چې زما زور ختم شى ما مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13998, 'Psalms 71:10', 'Psalms', 71, 10, '&nbsp;زما دشمنان زما خلاف خبرې کوى، څوک چې راپسې دى هغوئ زما د وژلو بندوبست کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13999, 'Psalms 71:11', 'Psalms', 71, 11, '&nbsp;دوئ وائى، ”خُدائ پاک ترې نه لاس اخستے دے نو ورپسې شئ او راټينګ يې کړئ. هيڅ څوک نشته چې هغۀ له خلاصون ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14000, 'Psalms 71:12', 'Psalms', 71, 12, '&nbsp;زما نه لرې مۀ اوسېږه، اے مالِکه خُدايه، زما پاکه خُدايه، ستا مِنت کوم ما ته زر راشه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');